    /// <summary>
    /// getPOLineTempRcvLimit method COC
    /// </summary>
    /// <returns> string value</returns>
    public static server str getPOLineTempRcvLimit()
    {
        str TempRcvLimit;
        SysDictTable      dictMetItemSiteSettingsSetup = new SysDictTable(tableNum(MetItemSiteSettingsSetup));
        str itemid;
        str siteid;

        itemid = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, PurchLineAllVersions),
            fieldStr(PurchLineAllVersions, itemid));

        siteid = SysComputedColumn::returnField(dataentityviewstr(PurchPurchaseOrderConfirmationLineEntity), dataEntityDataSourceStr(PurchPurchaseOrderConfirmationLineEntity, InventDim),
            fieldStr(InventDim, InventSiteId));


        TempRcvLimit = strFmt(@"SELECT TOP 1 %1 FROM %2 WHERE (%2.%3 = %4 AND %2.%5 = %6) OR %2.%3 = %4",
            dictMetItemSiteSettingsSetup.fieldName(fieldNum(MetItemSiteSettingsSetup, TempRcvLimit), DbBackend::Sql),
            dictMetItemSiteSettingsSetup.name(DbBackend::Sql),
            dictMetItemSiteSettingsSetup.fieldName(fieldNum(MetItemSiteSettingsSetup, ItemId), DbBackend::Sql),
            itemid,
            dictMetItemSiteSettingsSetup.fieldName(fieldNum(MetItemSiteSettingsSetup, InventSiteId), DbBackend::Sql),
            siteid);

        return TempRcvLimit;
    }

